//! Scene sink validation and addon-compatible manifest columns.
use std::{collections::{BTreeMap,BTreeSet},sync::Arc};
use serde_json::{json,Value};
use crate::{Geometry,Attr,AttrData,Error,Result,params::Params};
use super::{Inputs,NodeSpec,blender_input::numbers};
pub const SCENE_OBJECTS:NodeSpec=NodeSpec{ outputs: &["geometry"], cook_multi: None, cook_sidecar: None,name:"scene_objects",inputs:super::GEO,params:crate::params!("mode":"instances";"prefix":"MiniHou";"collection":"";"source":"";"id_attrib":"id";"piece_attrib":"piece";"attributes":"uv Cd N material_index";"max_objects":2000),cook:scene_objects};
#[derive(Clone,Debug)]pub struct Manifest{pub header:Value,pub arrays:BTreeMap<String,Attr>}
fn scene_objects(inputs:&Inputs,p:&Params)->Result<Geometry>{let g=inputs[0].first().ok_or_else(||Error::new("input 'geo' is not connected"))?;build_manifest("",p,g,"")?;Ok((**g).clone())}
fn gather(a:&Attr,rows:&[usize])->Attr{match &a.data{AttrData::F32(v)=>Attr::f32(a.width,rows.iter().flat_map(|&i|v[i*a.width..(i+1)*a.width].iter().copied()).collect()),AttrData::I32(v)=>Attr::i32(a.width,rows.iter().flat_map(|&i|v[i*a.width..(i+1)*a.width].iter().copied()).collect())}}
fn round(x:f64,places:i32)->f64{let f=10f64.powi(places);(x*f).round_ties_even()/f}
fn carry(g:&Geometry,arrays:&mut BTreeMap<String,Attr>,wanted:&str,maps:&[(&str,&str,&[usize])],always:&[&str],wildcard:bool)->Vec<String>{
    let mut names:Vec<String>=Vec::new();for n in wanted.split_whitespace().chain(always.iter().copied()){if !names.iter().any(|x|x==n){names.push(n.into());}}
    let mut carried=Vec::new();for &(src,dst,rows) in maps{let table=g.table(src);let ns=if wildcard&&names.iter().any(|n|n=="*"){table.keys().cloned().collect()}else{names.clone()};for name in ns{let key=format!("{dst}:{name}");if name=="P"||arrays.contains_key(&key){continue;}if wildcard&&name.starts_with("group_"){continue;}if let Some(a)=table.get(&name){if wildcard&&a.width>4{continue;}arrays.insert(key.clone(),gather(a,rows));carried.push(key);}}}carried
}
pub fn build_manifest(id:&str,p:&Params,g:&Geometry,key:&str)->Result<Manifest>{
    let mode=p.e("mode",&["instances","objects","pieces","curves","points"])?;let max=p.i("max_objects")?;
    let mut arrays=BTreeMap::new();let wanted=p.s("attributes")?;
    let mut body=match mode.as_str(){
        "instances"=>instances(g,p,max)?,
        "points"=>{if g.npoints==0{return Err(Error::new("points mode needs points: the input has none"));}if g.npoints>2_000_000{return Err(Error::new("points exceed limit (2,000,000)"));}let rows:Vec<_>=(0..g.npoints).collect();arrays.insert("P".into(),(**g.point.get("P").unwrap()).clone());let carried=carry(g,&mut arrays,&wanted,&[("point","point",&rows)],&["radius"],true);json!({"sources":[],"id":[0],"loc":[[0.,0.,0.]],"npts":[g.npoints],"attributes":carried})},
        "curves"=>{let mut prims=Vec::new();let mut corners=Vec::new();let mut points=Vec::new();let mut sizes=Vec::new();let mut cyclic=Vec::new();for i in 0..g.nprims(){let start=g.topology.prim_offsets[i] as usize;let end=g.topology.prim_offsets[i+1] as usize;if end-start<2{continue;}prims.push(i);corners.extend(start..end);points.extend(g.topology.vertex_point[start..end].iter().map(|&x|x as usize));sizes.push((end-start) as i32);cyclic.push(i32::from(g.topology.is_closed(i)&&end-start>=3));}if prims.is_empty(){return Err(Error::new("curves mode needs curves or polygons: the input has no primitive with 2 or more points"));}if points.len()>2_000_000{return Err(Error::new("curve points exceed limit (2,000,000)"));}arrays.insert("P".into(),gather(&g.point["P"],&points));arrays.insert("sizes".into(),Attr::i32(1,sizes));arrays.insert("cyclic".into(),Attr::i32(1,cyclic));let carried=carry(g,&mut arrays,&wanted,&[("point","point",&points),("vertex","point",&corners),("prim","prim",&prims)],&["radius","tilt"],true);json!({"sources":[],"id":[0],"loc":[[0.,0.,0.]],"npts":[points.len()],"ncurve":[prims.len()],"attributes":carried})},
        _=>objects(g,p,max,&wanted,&mut arrays)?,
    };
    let prefix=p.s("prefix")?;let prefix=if prefix.trim().is_empty(){"MiniHou"}else{prefix.trim()};let collection=p.s("collection")?;
    for (k,v) in [("type",json!("scene_objects")),("node",json!(id)),("key",json!(key)),("mode",json!(mode)),("prefix",json!(prefix.chars().take(60).collect::<String>())),("collection",json!((if collection.trim().is_empty(){prefix}else{collection.trim()}).chars().take(60).collect::<String>()))]{body[k]=v;}
    Ok(Manifest{header:body,arrays})
}
fn instances(g:&Geometry,p:&Params,max:i64)->Result<Value>{
    let source=p.s("source")?;let names=g.detail.get("instance_objects").and_then(Value::as_array).filter(|a|!a.is_empty());let inst=g.point.get("instance").filter(|a|a.width==1);
    let (sources,pick,src):(Vec<String>,Vec<usize>,Vec<usize>)=if let(Some(names),Some(inst))=(names,inst){let values=numbers(inst);let pick:Vec<_>=values.iter().enumerate().filter(|(_,x)|**x>0.&&**x<=names.len() as f64).map(|(i,_)|i).collect();let src=pick.iter().map(|&i|values[i] as usize-1).collect();(names.iter().map(|v|v.as_str().map(str::to_string).unwrap_or_else(||v.to_string())).collect(),pick,src)}else{if source.trim().is_empty(){return Err(Error::new("set 'source' to the Blender object to duplicate (or feed points from the instance node, which name their objects)"));}(vec![source.trim().into()],(0..g.npoints).collect(),vec![0;g.npoints])};
    if pick.len() as i64>max{return Err(Error::new(format!("{} objects is more than max_objects ({max})",pick.len())));}
    let idname=p.s("id_attrib")?;let mut ids:Vec<i64>=(0..pick.len() as i64).collect();if let Some(a)=g.point.get(&idname){let AttrData::I32(v)=&a.data else{return Err(Error::new(format!("point attribute {idname:?} must be an integer to identify objects")));};if a.width!=1{return Err(Error::new(format!("point attribute {idname:?} must be an integer to identify objects")));}ids=pick.iter().map(|&i|v[i] as i64).collect();if ids.iter().collect::<BTreeSet<_>>().len()!=ids.len(){return Err(Error::new(format!("point attribute {idname:?} has repeated values, so it cannot identify objects; fix it or clear id_attrib to use point numbers")));}}
    let rot=g.point.get("rot").filter(|a|a.width==3).map(|a|numbers(a));let scale=g.point.get("scale").filter(|a|a.width==3).map(|a|numbers(a));let ps=g.point.get("pscale").filter(|a|a.width==1).map(|a|numbers(a));
    let loc:Vec<[f64;3]>=pick.iter().map(|&i|std::array::from_fn(|k|round(g.p()[i*3+k] as f64,6))).collect();let rots:Vec<[f64;3]>=pick.iter().map(|&i|std::array::from_fn(|k|round(rot.as_ref().map_or(0.,|v|v[i*3+k]),7))).collect();let scales:Vec<[f64;3]>=pick.iter().map(|&i|std::array::from_fn(|k|round(scale.as_ref().map_or_else(||ps.as_ref().map_or(1.,|v|v[i]),|v|v[i*3+k]),6))).collect();
    let mut out=json!({"sources":sources,"id":ids,"src":src,"loc":loc,"rot":rots,"scale":scales});
    if let (Some(mats),Some(a))=(g.detail.get("materials").and_then(Value::as_array),g.point.get("material_id")){let ix=numbers(a);let col:Vec<_>=pick.iter().map(|&i|if ix[i]<0.{""}else{mats.get(ix[i] as usize).and_then(Value::as_str).unwrap_or("")}).collect();if col.iter().any(|s|!s.is_empty()){out["material"]=json!(col);}}
    Ok(out)
}
fn objects(g:&Geometry,p:&Params,max:i64,wanted:&str,arrays:&mut BTreeMap<String,Attr>)->Result<Value>{
    let t=&g.topology;let mesh:Vec<usize>=(0..g.nprims()).filter(|&i|t.is_closed(i)&&t.prim_offsets[i+1]-t.prim_offsets[i]>=3).collect();if mesh.is_empty(){return Err(Error::new("objects mode needs faces: there are none in the input"));}
    let name=p.s("piece_attrib")?;let mut groups:BTreeMap<i32,Vec<usize>>=BTreeMap::new();
    if let Some(a)=g.prim.get(&name){let AttrData::I32(labels)=&a.data else{return Err(Error::new(format!("primitive attribute {name:?} must be an integer to number the objects")));};if a.width!=1{return Err(Error::new(format!("primitive attribute {name:?} must be an integer to number the objects")));}for &i in &mesh{groups.entry(labels[i]).or_default().push(i);}}
    else{let mut adj=vec![Vec::new();g.npoints];for i in 0..g.nprims(){let pts=&t.vertex_point[t.prim_offsets[i] as usize..t.prim_offsets[i+1] as usize];for pair in pts.windows(2){adj[pair[0] as usize].push(pair[1] as usize);adj[pair[1] as usize].push(pair[0] as usize);}}let mut labels=vec![-1;g.npoints];let mut id=0;for i in 0..g.npoints{if labels[i]>=0{continue;}labels[i]=id;let mut stack=vec![i];while let Some(j)=stack.pop(){for &k in &adj[j]{if labels[k]<0{labels[k]=id;stack.push(k);}}}id+=1;}for &i in &mesh{groups.entry(labels[t.vertex_point[t.prim_offsets[i] as usize] as usize]).or_default().push(i);}}
    if groups.len() as i64>max{return Err(Error::new(format!("{} objects is more than max_objects ({max})",groups.len())));}
    let mut ids=Vec::new();let mut loc=Vec::new();let mut npts=Vec::new();let mut ncorner=Vec::new();let mut nprim=Vec::new();let mut pointrows=Vec::new();let mut cornerrows=Vec::new();let mut primrows=Vec::new();let mut pos=Vec::new();let mut vp=Vec::new();let mut sizes=Vec::new();
    for (id,prims) in groups{let corners:Vec<usize>=prims.iter().flat_map(|&i|t.prim_offsets[i] as usize..t.prim_offsets[i+1] as usize).collect();let pts:Vec<usize>=corners.iter().map(|&c|t.vertex_point[c] as usize).collect::<BTreeSet<_>>().into_iter().collect();let mut center=[0f64;3];for &pt in &pts{for k in 0..3{center[k]+=g.p()[pt*3+k] as f64;}}for k in 0..3{center[k]/=pts.len() as f64;}for &pt in &pts{for k in 0..3{pos.push((g.p()[pt*3+k] as f64-center[k]) as f32);}}for &c in &corners{vp.push(pts.binary_search(&(t.vertex_point[c] as usize)).unwrap() as i32);}sizes.extend(prims.iter().map(|&i|t.prim_offsets[i+1]-t.prim_offsets[i]));ids.push(id);loc.push(center.map(|x|round(x,6)));npts.push(pts.len());ncorner.push(corners.len());nprim.push(prims.len());pointrows.extend(pts);cornerrows.extend(corners);primrows.extend(prims);}
    if pointrows.len()>2_000_000{return Err(Error::new("objects exceed point limit (2,000,000)"));}arrays.insert("P".into(),Attr::f32(3,pos));arrays.insert("vp".into(),Attr::i32(1,vp));arrays.insert("sizes".into(),Attr::i32(1,sizes));
    let attributes=carry(g,arrays,wanted,&[("point","point",&pointrows),("vertex","vertex",&cornerrows),("prim","prim",&primrows)],&[],false);
    let mut out=json!({"sources":[],"id":ids,"loc":loc,"npts":npts,"ncorner":ncorner,"nprim":nprim,"attributes":attributes});if let Some(m)=g.detail.get("materials"){out["materials"]=m.clone();}Ok(out)
}
#[cfg(test)]mod tests{use super::*;
#[test]fn instance_ids_must_be_unique(){let mut g=Geometry::points_only(vec![0.;6]).unwrap();g.point.insert("id".into(),Arc::new(Attr::i32(1,vec![4,4])));let p=Params::resolve(SCENE_OBJECTS.params,json!({"source":"Cube"}).as_object()).unwrap();assert!(build_manifest("s",&p,&g,"k").is_err());}
#[test]fn objects_have_local_indices_and_centered_positions(){let g=Geometry::from_arrays(vec![0.,0.,0.,3.,0.,0.,0.,3.,0.],vec![0,1,2],vec![0,3],None).unwrap();let p=Params::resolve(SCENE_OBJECTS.params,json!({"mode":"objects"}).as_object()).unwrap();let m=build_manifest("s",&p,&g,"k").unwrap();assert_eq!(m.header["loc"],json!([[1.,1.,0.]]));assert_eq!(m.arrays["vp"],Attr::i32(1,vec![0,1,2]));assert_eq!(m.arrays["P"].as_f32().unwrap()[0],-1.);let legacy=Params::resolve(SCENE_OBJECTS.params,json!({"mode":"pieces"}).as_object()).unwrap();assert_eq!(build_manifest("s",&legacy,&g,"k").unwrap().arrays,m.arrays);}
}
